// FLOW PLAYBOOK: what each Klaviyo flow email should do.
// The Klaviyo webhook sends {"flow": "<key>", "step": <number>, "email": "..."}. The flow key picks an entry
// below, and the step picks the instructions for that email. Edit these to match your store.
// A flow key that isn't listed uses "default". "fallback" is sent if the AI can't write the email.
const PLAYBOOK = {
  welcome: {
    name: 'Welcome series',
    goal: 'Turn a new subscriber into a first-time buyer.',
    steps: {
      1: 'Welcome them, say what makes the store different, and show best sellers or products like the ones they viewed.',
      2: 'Tell the brand story or how the products are made. Recommend products that match what they viewed or added to cart.',
      3: 'Answer the common reasons people hesitate (fit, quality, shipping, returns) using only facts given here, and invite them to shop.',
    },
    products: 'Best sellers or products that match what they browsed.',
    discount: 'Never offer a discount.',
    fallback: { subject: 'Welcome to {store}', headline: 'Glad you are here', body: 'Thanks for joining us. Take a look at what our customers love most.', cta_text: 'Shop now' },
  },
  abandoned_checkout: {
    name: 'Abandoned checkout',
    goal: 'Bring the customer back to finish the checkout they started.',
    steps: {
      1: 'A friendly, short reminder about the exact items in their cart. No pressure.',
      2: 'Help them decide: what customers like about these items, and anything that removes doubt. Mention one related product.',
      3: 'Last reminder. You may offer a discount only if the discount rule allows it.',
    },
    products: 'One to three products that go well with the items in their cart, never the same items.',
    discount: 'Only on step 3, and only if they have placed fewer than 2 orders. Otherwise no discount.',
    fallback: { subject: 'You left something behind', headline: 'Your cart is saved', body: 'The items in your cart are waiting for you. Pick up where you left off whenever you are ready.', cta_text: 'Return to cart' },
  },
  browse_abandonment: {
    name: 'Browse abandonment',
    goal: 'Bring back a shopper who viewed products but did not add them to cart.',
    steps: {
      1: 'Mention the product they viewed most recently and why people like it.',
      2: 'Show alternatives to what they viewed, in case it was not quite right.',
    },
    products: 'The products they viewed, plus close alternatives.',
    discount: 'Never offer a discount.',
    fallback: { subject: 'Still thinking it over?', headline: 'Take another look', body: 'You were looking at some of our favorites. Here they are again.', cta_text: 'Take a look' },
  },
  post_purchase: {
    name: 'Post-purchase',
    goal: 'Make the customer happy with their order and lead to the next one.',
    steps: {
      1: 'Thank them for their order by name of the products, and give one useful tip for using or caring for what they bought.',
      2: 'Recommend products that go with what they bought.',
      3: 'Ask how they like their order and invite them to leave a review.',
    },
    products: 'Products that complement their last order. None on step 1 and step 3.',
    discount: 'Never offer a discount.',
    fallback: { subject: 'Thanks for your order', headline: 'Thank you', body: 'We hope you love your order. Reply to this email if there is anything we can help with.', cta_text: 'Visit the store' },
  },
  replenishment: {
    name: 'Replenishment',
    goal: 'Remind the customer to reorder before they run out.',
    steps: {
      1: 'Remind them it may be time to restock what they bought, using their order history and expected next order date if given.',
    },
    products: 'The products from their last order, then one related product.',
    discount: 'Never offer a discount.',
    fallback: { subject: 'Time to restock?', headline: 'Running low?', body: 'It has been a while since your last order. Restock your favorites in a few clicks.', cta_text: 'Reorder now' },
  },
  win_back: {
    name: 'Win-back',
    goal: 'Re-engage a customer who has not bought in a while.',
    steps: {
      1: 'Show what is new since their last order, linked to what they bought before.',
      2: 'A warm last attempt. You may offer a discount only if the discount rule allows it.',
    },
    products: 'New arrivals or best sellers related to their past orders.',
    discount: 'Only on step 2, and only if their churn risk is above 0.5 or unknown.',
    fallback: { subject: 'We miss you', headline: 'It has been a while', body: 'A lot has changed since your last visit. Come see what is new.', cta_text: 'See what is new' },
  },
  default: {
    name: 'Flow email',
    goal: 'Send a helpful, personal email that leads to a purchase.',
    steps: {},
    products: 'Products that fit what this customer viewed or bought.',
    discount: 'Never offer a discount.',
    fallback: { subject: 'Picked for you', headline: 'Picked for you', body: 'Here are a few things we think you will like.', cta_text: 'Shop now' },
  },
};

const settings = $('Settings').first().json;
const body = $('Klaviyo Flow Webhook').first().json.body ?? {};
const email = String(body.email ?? '').trim().toLowerCase();

// No email means Klaviyo sent an empty variable, so there is no one to write to
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return [];

const flow = String(body.flow ?? 'default').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '') || 'default';
const step = Math.max(1, parseInt(body.step, 10) || 1);
const entry = PLAYBOOK[flow] ?? PLAYBOOK.default;
const ctaOverride = /^https?:\/\/\S+$/i.test(String(body.cta_url ?? '').trim()) ? String(body.cta_url).trim() : '';
const fill = (s) => String(s ?? '').replace(/\{store\}/g, settings.store_name);

return [{
  json: {
    email,
    flow,
    flow_name: entry.name,
    step,
    goal: entry.goal,
    step_instructions: entry.steps[step] ?? entry.steps[Object.keys(entry.steps).pop()] ?? entry.goal,
    product_guidance: entry.products,
    discount_rule: entry.discount,
    note: String(body.note ?? '').trim().slice(0, 500),
    cta_url_override: ctaOverride,
    fallback: Object.fromEntries(Object.entries(entry.fallback).map(([k, v]) => [k, fill(v)])),
  },
}];

// Turns the customer's Klaviyo profile and recent activity into a short brief for the AI agent:
// orders, predictions, the open cart, recently viewed products, and email engagement.
const request = $('Flow Playbook').first().json;
const profileRes = $('Find Klaviyo Profile').first().json;
const activityRes = $('Get Customer Activity').first().json;

const profile = Array.isArray(profileRes.data) ? profileRes.data[0] : null;
const a = profile?.attributes ?? {};
const events = Array.isArray(activityRes.data) ? activityRes.data : [];
const metricNames = new Map((activityRes.included ?? [])
  .filter((x) => x.type === 'metric')
  .map((m) => [m.id, String(m.attributes?.name ?? '')]));

const text = (v) => (v === undefined || v === null ? '' : String(v).trim());
const pick = (o, keys) => keys.map((k) => o?.[k]).find((v) => v !== undefined && v !== null && v !== '');
const day = (iso) => text(iso).slice(0, 10);
const num = (v) => {
  const n = parseFloat(String(v ?? '').replace(/[^0-9.-]/g, ''));
  return Number.isFinite(n) ? n : null;
};

// Finds the first value anywhere in the event whose key looks like a checkout link
const findCheckoutUrl = (obj, depth = 0) => {
  if (!obj || typeof obj !== 'object' || depth > 4) return '';
  for (const key of ['responsive_checkout_url', 'checkout_url', 'CheckoutURL', 'checkoutUrl']) {
    if (/^https?:\/\//i.test(text(obj[key]))) return text(obj[key]);
  }
  for (const value of Object.values(obj)) {
    const found = findCheckoutUrl(value, depth + 1);
    if (found) return found;
  }
  return '';
};

const product = (p) => ({
  title: text(pick(p, ['ProductName', 'Name', 'Title', 'title', 'name', 'product_name'])),
  url: text(pick(p, ['URL', 'ProductURL', 'Url', 'url', 'product_url'])),
  image_url: text(pick(p, ['ImageURL', 'ImageUrl', 'image_url', 'Image'])) || text(p?.product?.images?.[0]?.src),
  price: text(pick(p, ['Price', 'ItemPrice', 'line_price', 'price'])),
  quantity: num(pick(p, ['Quantity', 'quantity'])) ?? 1,
});

const lineItems = (props) => {
  const lists = [props?.$extra?.line_items, props?.extra?.line_items, props?.line_items, props?.Items];
  const list = lists.find((l) => Array.isArray(l) && l.length) ?? [];
  return list
    .map((i) => (typeof i === 'string' ? { title: i, url: '', image_url: '', price: '', quantity: 1 } : product(i)))
    .filter((i) => i.title)
    .slice(0, 8);
};

// Sort the activity into the kinds of events the agent cares about (newest first)
const kinds = { order: [], checkout: [], cart: [], viewed: [], opened: [], clicked: [], received: [] };
for (const e of events) {
  const name = metricNames.get(e.relationships?.metric?.data?.id) ?? '';
  const ev = { when: e.attributes?.datetime, props: e.attributes?.event_properties ?? {} };
  if (/^placed order$/i.test(name)) kinds.order.push(ev);
  else if (/checkout/i.test(name) && /start/i.test(name)) kinds.checkout.push(ev);
  else if (/added to cart/i.test(name)) kinds.cart.push(ev);
  else if (/viewed product/i.test(name)) kinds.viewed.push(ev);
  else if (/opened email/i.test(name)) kinds.opened.push(ev);
  else if (/clicked email/i.test(name)) kinds.clicked.push(ev);
  else if (/received email/i.test(name)) kinds.received.push(ev);
}

const lastCheckout = kinds.checkout[0];
const cartItems = lastCheckout ? lineItems(lastCheckout.props) : (kinds.cart[0] ? [product(kinds.cart[0].props)].filter((i) => i.title) : []);
const checkoutUrl = request.cta_url_override || (lastCheckout ? findCheckoutUrl(lastCheckout.props) : '');

const viewed = [];
for (const v of kinds.viewed) {
  const p = product(v.props);
  if (p.title && !viewed.some((x) => x.title === p.title)) viewed.push(p);
  if (viewed.length >= 6) break;
}

const pa = a.predictive_analytics ?? {};
const props = Object.entries(a.properties ?? {})
  .filter(([k, v]) => !k.startsWith('$') && !k.startsWith('ai_') && v !== null && v !== '' && typeof v !== 'object')
  .slice(0, 10);
const thirtyDaysAgo = $now.minus({ days: 30 }).toISO();
const consent = a.subscriptions?.email?.marketing?.consent ?? '';

const lines = [];
lines.push(`First name: ${text(a.first_name) || 'unknown (do not use a name)'}`);
if (a.location?.city || a.location?.country) lines.push(`Location: ${[a.location?.city, a.location?.region, a.location?.country].filter(Boolean).join(', ')}`);
if (a.created) lines.push(`Customer profile created: ${day(a.created)}`);
if (consent) lines.push(`Email marketing consent: ${consent}`);
lines.push(`Orders placed: ${pa.historic_number_of_orders ?? kinds.order.length}${pa.average_order_value ? `, average order value ${pa.average_order_value}` : ''}`);
for (const o of kinds.order.slice(0, 3)) {
  const items = lineItems(o.props).map((i) => i.title).join('; ') || text(pick(o.props, ['ItemNames'])) || 'items not listed';
  lines.push(`- Order on ${day(o.when)}: ${items}${o.props.$value ? ` (total ${o.props.$value})` : ''}`);
}
if (pa.predicted_clv !== undefined || pa.churn_probability !== undefined || pa.expected_date_of_next_order) {
  lines.push(`Klaviyo predictions: predicted lifetime value ${pa.predicted_clv ?? 'unknown'}, churn risk ${pa.churn_probability ?? 'unknown'}, expected next order ${day(pa.expected_date_of_next_order) || 'unknown'}, average days between orders ${pa.average_days_between_orders ?? 'unknown'}`);
}
if (lastCheckout) {
  lines.push(`Open checkout started ${day(lastCheckout.when)}${lastCheckout.props.$value ? `, cart value ${lastCheckout.props.$value}` : ''}:`);
  for (const i of cartItems) lines.push(`- ${i.title}${i.quantity > 1 ? ` x${i.quantity}` : ''}${i.price ? ` (${i.price})` : ''}`);
} else if (cartItems.length) {
  lines.push(`Last added to cart: ${cartItems.map((i) => i.title).join('; ')}`);
}
if (viewed.length) lines.push(`Recently viewed (newest first): ${viewed.map((v) => v.title).join('; ')}`);
lines.push(`Email engagement: last opened ${day(kinds.opened[0]?.when) || 'never'}, last clicked ${day(kinds.clicked[0]?.when) || 'never'}, ${kinds.clicked.filter((c) => text(c.when) >= thirtyDaysAgo).length} clicks in the last 30 days`);
const subjects = [...new Set(kinds.received.map((r) => text(pick(r.props, ['Subject', 'subject']))).filter(Boolean))].slice(0, 5);
if (subjects.length) lines.push(`Recent email subjects they received (do not repeat these): ${subjects.join(' | ')}`);
if (props.length) lines.push(`Profile properties: ${props.map(([k, v]) => `${k}: ${String(v).slice(0, 80)}`).join('; ')}`);
if (!profile) lines.push('No Klaviyo profile was found for this email, so there is no history. Write a helpful general email.');

return [{
  json: {
    ...request,
    profile_id: profile?.id ?? '',
    first_name: text(a.first_name),
    order_count: Number(pa.historic_number_of_orders ?? kinds.order.length) || 0,
    churn_probability: pa.churn_probability ?? null,
    cart_items: cartItems,
    checkout_url: checkoutUrl,
    brief: lines.join('\n'),
  },
}];

