parameters.jsCode:
// Checks the agent's email, looks up the real product details from Shopify, and builds the
// "AI Email Ready" event. Klaviyo's AI sender flow uses the event's properties as the email content.
const settings = $('Settings').first().json;
const brief = $('Build Customer Brief').first().json;
const ai = $('Lifecycle Email Agent').first().json.output ?? {};
const shop = $input.first().json;

// Plain text only: no HTML, and no {{ }} or {% %} that Klaviyo would try to run as template code
const clean = (v, max) => String(v ?? '')
  .replace(/<[^>]*>/g, '')
  .replace(/\{\{|\}\}|\{%|%\}/g, '')
  .replace(/[ \t]+/g, ' ')
  .replace(/ *\n */g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim()
  .slice(0, max);
const storeUrl = String(settings.store_url).replace(/\/$/, '');

const money = (amount, currency) => {
  const n = Number(amount);
  if (!Number.isFinite(n)) return '';
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: currency || 'USD' }).format(n);
  } catch (e) {
    return `${currency} ${n.toFixed(2)}`;
  }
};

// Only active, in-stock products that Shopify returned are used, in the agent's order
const nodes = (shop?.data?.nodes ?? []).filter(Boolean);
const products = nodes
  .filter((p) => p.status === 'ACTIVE' && (!p.tracksInventory || p.totalInventory > 0))
  .slice(0, Number(settings.max_products) || 3)
  .map((p) => ({
    id: p.id,
    title: p.title,
    url: p.onlineStoreUrl || `${storeUrl}/products/${p.handle}`,
    image_url: p.featuredMedia?.preview?.image?.url ?? '',
    price: money(p.priceRangeV2?.minVariantPrice?.amount, p.priceRangeV2?.minVariantPrice?.currencyCode),
  }));

const paragraphs = clean(ai.body, 1200).split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean).slice(0, 4);
const fb = brief.fallback;
const subject = clean(ai.subject, 80) || fb.subject;
const content = {
  flow: brief.flow,
  flow_name: brief.flow_name,
  step: brief.step,
  subject,
  preview_text: clean(ai.preview_text, 140),
  headline: clean(ai.headline, 90) || fb.headline,
  body_paragraphs: paragraphs.length ? paragraphs : [fb.body],
  cta_text: clean(ai.cta_text, 30) || fb.cta_text,
  cta_url: brief.cta_url_override || brief.checkout_url || storeUrl,
  products,
  has_products: products.length > 0,
  cart_items: brief.cart_items,
  has_cart: brief.cart_items.length > 0,
  offer_discount: ai.offer_discount === true,
  ai_generated: true,
  ai_reasoning: clean(ai.reasoning, 300),
};

// The same flow step for the same person on the same day only sends once, even if Klaviyo retries the webhook
const uniqueId = `ai-${content.flow}-${content.step}-${brief.profile_id || brief.email}-${$now.toFormat('yyyyLLdd')}`;

return [{
  json: {
    email: brief.email,
    ...content,
    klaviyo_event: {
      data: {
        type: 'event',
        attributes: {
          properties: content,
          unique_id: uniqueId,
          metric: { data: { type: 'metric', attributes: { name: settings.klaviyo_event_name } } },
          profile: { data: { type: 'profile', attributes: { email: brief.email } } },
        },
      },
    },
  },
}];

// Used when the AI agent fails: builds the same event with the playbook's fallback copy,
// so the customer still gets the email from your Klaviyo flow.
const settings = $('Settings').first().json;
const brief = $('Build Customer Brief').first().json;
const fb = brief.fallback;
const storeUrl = String(settings.store_url).replace(/\/$/, '');

const content = {
  flow: brief.flow,
  flow_name: brief.flow_name,
  step: brief.step,
  subject: fb.subject,
  preview_text: '',
  headline: fb.headline,
  body_paragraphs: [fb.body],
  cta_text: fb.cta_text,
  cta_url: brief.cta_url_override || brief.checkout_url || storeUrl,
  products: [],
  has_products: false,
  cart_items: brief.cart_items,
  has_cart: brief.cart_items.length > 0,
  offer_discount: false,
  ai_generated: false,
  ai_reasoning: `The AI agent failed, so fallback copy was used: ${String($json.error?.message ?? $json.error ?? 'unknown error').slice(0, 200)}`,
};
const uniqueId = `ai-${content.flow}-${content.step}-${brief.profile_id || brief.email}-${$now.toFormat('yyyyLLdd')}`;

return [{
  json: {
    email: brief.email,
    ...content,
    klaviyo_event: {
      data: {
        type: 'event',
        attributes: {
          properties: content,
          unique_id: uniqueId,
          metric: { data: { type: 'metric', attributes: { name: settings.klaviyo_event_name } } },
          profile: { data: { type: 'profile', attributes: { email: brief.email } } },
        },
      },
    },
  },
}];

// Reads the campaign request from the form, or uses the weekly brief from Settings for the weekly run.
const settings = $('Settings').first().json;
const form = $('Campaign Request Form').isExecuted ? $('Campaign Request Form').first().json : null;
const text = (v, max = 1000) => String(v ?? '').trim().slice(0, max);

return [{
  json: {
    source: form ? 'form' : 'weekly planner',
    brief: form ? text(form.brief, 2000) : text(settings.weekly_brief, 2000),
    focus: form ? text(form.focus) : '',
    audience: form ? text(form.audience) : '',
    offer: form ? text(form.offer, 300) : '',
    // Shopify order search for the last 30 days, used to find best sellers
    orders_query: `created_at:>=${$now.minus({ days: 30 }).toISODate()}`,
  },
}];

// Builds the Campaign Strategist Agent's brief from Klaviyo and Shopify data: the segments it can send to,
// how past campaigns performed, and the store's best sellers, new arrivals, and products with the most stock.
const settings = $('Settings').first().json;
const req = $('Read Campaign Request').first().json;

const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
const pct = (v) => `${(num(v) * 100).toFixed(1)}%`;

// Klaviyo segments (one item per page of results)
const segments = $('Get Klaviyo Segments').all()
  .flatMap((i) => (Array.isArray(i.json.data) ? i.json.data : []))
  .map((s) => ({ id: s.id, name: String(s.attributes?.name ?? ''), starred: s.attributes?.is_starred === true }))
  .filter((s) => s.id && s.name);
if (!segments.length) {
  throw new Error('No active Klaviyo segments were found. Check the Klaviyo API credential and its segments:read scope.');
}

// Past campaign results for the last 90 days
const report = $('Get Campaign Results').first().json;
const campaigns = (report?.data?.attributes?.results ?? [])
  .map((r) => ({
    name: String(r.groupings?.campaign_message_name || r.groupings?.campaign_id || ''),
    delivered: num(r.statistics?.delivered),
    open_rate: r.statistics?.open_rate,
    click_rate: r.statistics?.click_rate,
    conversion_rate: r.statistics?.conversion_rate,
    revenue: num(r.statistics?.conversion_value),
  }))
  .filter((c) => c.name && c.delivered > 0)
  .sort((a, b) => b.revenue - a.revenue)
  .slice(0, 10);

// Shopify products
const store = $('Get Store Data').first().json?.data ?? {};
const inStock = (p) => p && p.status === 'ACTIVE' && (!p.tracksInventory || p.totalInventory > 0);
const price = (p) => {
  const m = p.priceRangeV2?.minVariantPrice;
  return m ? `${Number(m.amount).toFixed(2)} ${m.currencyCode}` : 'price unknown';
};
const line = (p, extra = '') => `${p.id} | ${p.title} | ${price(p)} | ${p.productType || 'no type'} | stock ${p.tracksInventory ? p.totalInventory : 'not tracked'}${extra}`;

const sold = new Map();
for (const order of store.orders?.nodes ?? []) {
  for (const li of order.lineItems?.nodes ?? []) {
    if (!li.product?.id) continue;
    const s = sold.get(li.product.id) ?? { product: li.product, units: 0 };
    s.units += num(li.quantity) || 1;
    sold.set(li.product.id, s);
  }
}
const bestSellers = [...sold.values()].filter((s) => inStock(s.product)).sort((a, b) => b.units - a.units).slice(0, 10);
const newArrivals = (store.newArrivals?.nodes ?? []).filter(inStock).slice(0, 8);
const topStock = (store.topStock?.nodes ?? []).filter(inStock).slice(0, 8);

const section = (title, rows, empty) => `${title}\n${rows.length ? rows.join('\n') : empty}`;
const prompt = [
  'CAMPAIGN REQUEST',
  `Source: ${req.source}`,
  `Brief: ${req.brief}`,
  `Products or collection to feature: ${req.focus || 'your choice, based on the data'}`,
  `Audience wanted: ${req.audience || 'your choice, from the segments below'}`,
  `Offer to include: ${req.offer || 'none. Do not offer a discount.'}`,
  `Today: ${$now.toFormat('yyyy-MM-dd (cccc)')}`,
  '',
  section('KLAVIYO SEGMENTS (id | name | starred)', segments.map((s) => `${s.id} | ${s.name}${s.starred ? ' | starred' : ''}`), 'none'),
  '',
  section('PAST CAMPAIGNS, LAST 90 DAYS, MOST REVENUE FIRST (name | delivered | open rate | click rate | order rate | revenue)',
    campaigns.map((c) => `${c.name} | ${c.delivered} | ${pct(c.open_rate)} | ${pct(c.click_rate)} | ${pct(c.conversion_rate)} | ${c.revenue.toFixed(2)}`),
    'No campaign results found.'),
  '',
  section('SHOPIFY BEST SELLERS, LAST 30 DAYS (product id | title | price | type | stock | units sold)',
    bestSellers.map((s) => line(s.product, ` | ${s.units} sold`)), 'No recent orders found.'),
  '',
  section('NEW ARRIVALS (product id | title | price | type | stock)', newArrivals.map((p) => line(p)), 'none'),
  '',
  section('MOST STOCK ON HAND (product id | title | price | type | stock)', topStock.map((p) => line(p)), 'none'),
].join('\n');

return [{
  json: {
    revision: 0,
    prompt,
    original_prompt: prompt,
    segments,
    request: req,
  },
}];

