// Checks the agent's campaign, looks up the real product details from Shopify, and builds the email HTML,
// the Klaviyo template, and the draft campaign request.
const settings = $('Settings').first().json;
const ctx = $('Build Campaign Context').first().json;
const ai = $('Campaign Strategist Agent').first().json.output ?? {};
const shop = $input.first().json;
const revision = $('Prepare Revision').isExecuted ? $('Prepare Revision').first().json.revision : 0;

// Plain text only: no HTML, and no {{ }} or {% %} that Klaviyo would try to run as template code
const clean = (v, max) => String(v ?? '')
  .replace(/<[^>]*>/g, '')
  .replace(/\{\{|\}\}|\{%|%\}/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, max);
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const storeUrl = String(settings.store_url).replace(/\/$/, '');
const storeHost = (storeUrl.match(/^https?:\/\/([^/?#]+)/i)?.[1] ?? '').toLowerCase();

// The audience must be one of the account's segments
const segment = ctx.segments.find((s) => s.id === String(ai.segment_id ?? '').trim());
if (!segment) {
  throw new Error(`The agent chose segment "${ai.segment_id}", which is not one of your active Klaviyo segments. Run the campaign again.`);
}

const money = (amount, currency) => {
  const n = Number(amount);
  if (!Number.isFinite(n)) return '';
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: currency || 'USD' }).format(n);
  } catch (e) {
    return `${currency} ${n.toFixed(2)}`;
  }
};

// Only active, in-stock products that Shopify returned are used, in the agent's order
const products = (shop?.data?.nodes ?? [])
  .filter((p) => p && p.status === 'ACTIVE' && (!p.tracksInventory || p.totalInventory > 0))
  .slice(0, 6)
  .map((p) => ({
    id: p.id,
    title: p.title,
    url: p.onlineStoreUrl || `${storeUrl}/products/${p.handle}`,
    image_url: p.featuredMedia?.preview?.image?.url ?? '',
    price: money(p.priceRangeV2?.minVariantPrice?.amount, p.priceRangeV2?.minVariantPrice?.currencyCode),
  }));

const subject = clean(ai.subject, 80);
if (!subject) throw new Error('The agent did not return a subject line. Run the campaign again.');
const headline = clean(ai.headline, 90) || subject;
const intro = clean(ai.intro, 600);
const sections = (Array.isArray(ai.sections) ? ai.sections : [])
  .map((s) => ({ heading: clean(s?.heading, 60), text: clean(s?.text, 500) }))
  .filter((s) => s.heading || s.text)
  .slice(0, 3);
const offer = clean(ai.offer_text, 200);
const ctaText = clean(ai.cta_text, 30) || 'Shop now';
// The button only links to your own store
const aiCta = String(ai.cta_url ?? '').trim();
const ctaUrl = /^https?:\/\//i.test(aiCta) && (aiCta.match(/^https?:\/\/([^/?#]+)/i)?.[1] ?? '').toLowerCase() === storeHost ? aiCta : storeUrl;
const color = /^#[0-9a-f]{3,8}$/i.test(String(settings.brand_color)) ? settings.brand_color : '#111827';

// ---------- Email HTML (table layout with inline styles, so it renders in every email client)
const font = 'font-family:Arial,Helvetica,sans-serif;';
const button = `<table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px auto;"><tr><td style="background:${color};border-radius:6px;">`
  + `<a href="${esc(ctaUrl)}" style="display:inline-block;padding:14px 28px;${font}font-size:16px;font-weight:bold;color:#ffffff;text-decoration:none;">${esc(ctaText)}</a></td></tr></table>`;
const header = settings.logo_url
  ? `<img src="${esc(settings.logo_url)}" alt="${esc(settings.store_name)}" width="160" style="display:block;margin:0 auto;max-width:160px;height:auto;border:0;">`
  : `<div style="${font}font-size:20px;font-weight:bold;text-align:center;color:${color};">${esc(settings.store_name)}</div>`;
const productCell = (p) => `<td width="50%" valign="top" style="padding:8px;text-align:center;">`
  + (p.image_url ? `<a href="${esc(p.url)}"><img src="${esc(p.image_url)}" alt="${esc(p.title)}" width="250" style="display:block;width:100%;max-width:250px;height:auto;margin:0 auto;border:0;border-radius:6px;"></a>` : '')
  + `<div style="${font}font-size:15px;font-weight:bold;color:#111827;margin-top:10px;">${esc(p.title)}</div>`
  + (p.price ? `<div style="${font}font-size:14px;color:#4b5563;margin-top:4px;">${esc(p.price)}</div>` : '')
  + `<a href="${esc(p.url)}" style="${font}font-size:14px;color:${color};font-weight:bold;display:inline-block;margin-top:8px;">Shop now</a></td>`;
const productRows = [];
for (let i = 0; i < products.length; i += 2) {
  productRows.push(`<tr>${productCell(products[i])}${products[i + 1] ? productCell(products[i + 1]) : '<td width="50%"></td>'}</tr>`);
}

const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(subject)}</title></head>
<body style="margin:0;padding:0;background:#f4f4f5;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5;"><tr><td align="center" style="padding:24px 12px;">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border-radius:8px;">
<tr><td style="padding:28px 32px 8px;">${header}</td></tr>
<tr><td style="padding:16px 32px 0;">
<h1 style="${font}font-size:28px;line-height:1.25;color:#111827;margin:0 0 16px;text-align:center;">${esc(headline)}</h1>
<p style="${font}font-size:16px;line-height:1.6;color:#374151;margin:0 0 12px;">Hi {{ first_name|default:'there' }},</p>
${intro ? `<p style="${font}font-size:16px;line-height:1.6;color:#374151;margin:0 0 12px;">${esc(intro)}</p>` : ''}
${offer ? `<div style="${font}font-size:16px;font-weight:bold;text-align:center;color:${color};border:2px dashed ${color};border-radius:6px;padding:14px;margin:16px 0;">${esc(offer)}</div>` : ''}
${button}
${sections.map((s) => `${s.heading ? `<h2 style="${font}font-size:20px;color:#111827;margin:20px 0 8px;">${esc(s.heading)}</h2>` : ''}${s.text ? `<p style="${font}font-size:16px;line-height:1.6;color:#374151;margin:0 0 12px;">${esc(s.text)}</p>` : ''}`).join('\n')}
</td></tr>
${productRows.length ? `<tr><td style="padding:8px 24px 16px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">${productRows.join('')}</table></td></tr>` : ''}
<tr><td style="padding:0 32px 24px;">${products.length ? button : ''}</td></tr>
<tr><td style="padding:20px 32px 28px;border-top:1px solid #e5e7eb;${font}font-size:12px;line-height:1.6;color:#6b7280;text-align:center;">
${esc(settings.footer_text)}<br>
<a href="{% unsubscribe_link %}" style="color:#6b7280;">Unsubscribe</a>
</td></tr>
</table>
</td></tr></table>
</body></html>`;

const date = $now.toFormat('yyyy-MM-dd');
const campaignName = `${clean(ai.campaign_name, 80) || subject} (AI ${date}${revision ? `, v${revision + 1}` : ''})`;

// The draft campaign: one audience (the segment) and one email message that uses the new template
const campaignBody = {
  data: {
    type: 'campaign',
    attributes: {
      definition: {
        name: campaignName,
        description: clean(ai.reasoning, 500),
        send_settings: { send_strategy: 'simple', send_timezone: settings.timezone },
      },
      audiences: [{ temporary_id: 'audience_1', name: segment.name, included: [segment.id], excluded: [] }],
      messages: [{
        audience_temporary_id: 'audience_1',
        name: campaignName,
        variations: [{
          definition: {
            name: 'Email',
            details: {
              channel: 'email',
              template_id: '__TEMPLATE_ID__',
              subject,
              preview_text: clean(ai.preview_text, 140),
              from_email: settings.from_email,
              from_label: settings.from_label,
              reply_to_email: settings.from_email,
            },
          },
        }],
      }],
    },
  },
};

return [{
  json: {
    revision,
    campaign_name: campaignName,
    segment_id: segment.id,
    segment_name: segment.name,
    subject,
    preview_text: clean(ai.preview_text, 140),
    headline,
    offer,
    products,
    reasoning: clean(ai.reasoning, 600),
    template_body: { data: { type: 'template', attributes: { name: `AI campaign: ${campaignName}`.slice(0, 250), editor_type: 'CODE', html } } },
    campaign_body_json: JSON.stringify(campaignBody),
  },
}];

// Builds the Slack message that asks for approval, with everything needed to decide.
const settings = $('Settings').first().json;
const email = $('Build Campaign Email').first().json;
const campaign = $('Create Draft Campaign').first().json;
const messages = $('Get Campaign Message').first().json;
const testSend = $('Send Test Email').first().json;
const size = $('Get Audience Size').first().json;
const req = $('Build Campaign Context').first().json.request;

const campaignId = campaign?.data?.id ?? '';
const messageId = (Array.isArray(messages?.data) ? messages.data[0]?.id : '') || campaign?.data?.relationships?.['campaign-messages']?.data?.[0]?.id || '';
if (!campaignId) {
  const reason = campaign?.error?.message ?? JSON.stringify(campaign?.errors ?? campaign).slice(0, 300);
  throw new Error(`Klaviyo did not create the draft campaign: ${reason}`);
}
const people = size?.data?.attributes?.profile_count;
const testNote = testSend?.error
  ? `The test email could not be sent (${String(testSend.error.message ?? testSend.error).slice(0, 120)}).`
  : `A test email was sent to ${settings.approver_email}.`;

const lines = [
  `*New AI campaign draft${email.revision ? ` (version ${email.revision + 1})` : ''}* from the ${req.source}`,
  `*Campaign:* ${email.campaign_name}`,
  `*Audience:* ${email.segment_name}${Number.isFinite(people) ? ` (${people.toLocaleString('en-US')} people)` : ''}`,
  `*Subject:* ${email.subject}`,
  `*Preview text:* ${email.preview_text || '(none)'}`,
  `*Headline:* ${email.headline}`,
  email.offer ? `*Offer:* ${email.offer}` : '*Offer:* none',
  `*Products:* ${email.products.map((p) => `${p.title} (${p.price})`).join(', ') || 'none'}`,
  `*Why:* ${email.reasoning}`,
  '',
  `${testNote} The draft is in Klaviyo under Campaigns.`,
];

return [{
  json: {
    campaign_id: campaignId,
    message_id: messageId,
    audience_size: Number.isFinite(people) ? people : null,
    slack_message: lines.join('\n').slice(0, 3500),
  },
}];

// Reads the reviewer's answer from Slack: send now, schedule, revise with notes, or keep as a draft.
const settings = $('Settings').first().json;
const approval = $('Build Approval Message').first().json;
const email = $('Build Campaign Email').first().json;
const answer = $json.data ?? null;
const maxRevisions = Number(settings.max_revisions) || 3;

let decision = 'draft';
let note = 'No answer in Slack before the time limit, so the campaign was kept as a draft.';
let sendTime = '';
const choice = String(answer?.decision ?? '');
const notes = String(answer?.notes ?? '').trim().slice(0, 1500);

if (choice.startsWith('Send now')) {
  decision = 'send_now';
  note = '';
} else if (choice.startsWith('Schedule')) {
  const typed = String(answer?.send_time ?? '').trim();
  const when = DateTime.fromFormat(typed, 'yyyy-MM-dd HH:mm', { zone: settings.timezone });
  if (!when.isValid) {
    note = `"${typed}" isn't a send time in the format 2026-11-12 10:00, so the campaign was kept as a draft.`;
  } else if (when <= $now.plus({ minutes: 15 })) {
    note = `${typed} is less than 15 minutes away or in the past, so the campaign was kept as a draft.`;
  } else {
    decision = 'schedule';
    sendTime = when.toUTC().toISO({ suppressMilliseconds: true });
    note = `${when.toFormat('cccc, LLL d, yyyy, h:mm a')} (${settings.timezone})`;
  }
} else if (choice.startsWith('Revise')) {
  if (email.revision + 1 >= maxRevisions) {
    note = `This was version ${email.revision + 1} of ${maxRevisions}, so it was kept as a draft instead of being revised again.`;
  } else {
    decision = 'revise';
    note = notes || 'Try a different angle and subject line.';
  }
} else if (answer) {
  note = 'Kept as a draft in Klaviyo, as requested.';
}

return [{
  json: {
    decision,
    note,
    send_time: sendTime,
    feedback: decision === 'revise' ? note : '',
    campaign_id: approval.campaign_id,
    message_id: approval.message_id,
  },
}];

// Sends the campaign back to the agent with the reviewer's notes and the previous draft.
const ctx = $('Build Campaign Context').first().json;
const email = $('Build Campaign Email').first().json;
const decision = $('Read Decision').first().json;
const revision = email.revision + 1;

const previous = [
  `Audience: ${email.segment_name} (${email.segment_id})`,
  `Subject: ${email.subject}`,
  `Preview text: ${email.preview_text}`,
  `Headline: ${email.headline}`,
  `Offer: ${email.offer || 'none'}`,
  `Products: ${email.products.map((p) => `${p.id} ${p.title}`).join('; ') || 'none'}`,
].join('\n');

return [{
  json: {
    ...ctx,
    revision,
    prompt: `${ctx.original_prompt}\n\nREVISION ${revision}\nYour previous draft:\n${previous}\n\nFeedback from the reviewer: ${decision.feedback}\n\nWrite a new version of the campaign that follows this feedback. Keep what the reviewer did not ask to change.`,
  },
}];

// Writes the Slack confirmation: sent, scheduled, kept as a draft, or an error from Klaviyo.
const decision = $('Read Decision').first().json;
const email = $('Build Campaign Email').first().json;
const approval = $('Build Approval Message').first().json;
const res = $json;

const audience = `${email.segment_name}${approval.audience_size !== null ? ` (${approval.audience_size.toLocaleString('en-US')} people)` : ''}`;
const error = res.error ? String(res.error.message ?? res.error).slice(0, 300) : '';

let text;
if (decision.decision === 'send_now' && !error) {
  text = `:white_check_mark: *Sending now:* "${email.campaign_name}" to ${audience}.`;
} else if (decision.decision === 'schedule' && !error) {
  text = `:calendar: *Scheduled* for ${decision.note}: "${email.campaign_name}" to ${audience}.`;
} else if (error) {
  text = `:warning: Klaviyo returned an error, so "${email.campaign_name}" is still a draft in Klaviyo: ${error}`;
} else {
  text = `:memo: "${email.campaign_name}" is a draft in Klaviyo. ${decision.note}`;
}

return [{ json: { text } }];
